package care.tend.habit;
import care.tend.item.LifeItem;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.LocalDate;import static org.assertj.core.api.Assertions.assertThat;
class HabitRulesTest{private LifeItem habit(){var h=new LifeItem();h.habitType="DURATION";h.minimumTarget=BigDecimal.TEN;h.idealTarget=BigDecimal.valueOf(60);return h;}@Test void minimumTargetIsMeaningfulPartialProgress(){assertThat(HabitRules.deriveState(habit(),BigDecimal.TEN)).isEqualTo("PARTIAL");}@Test void idealTargetIsCompleted(){assertThat(HabitRules.deriveState(habit(),BigDecimal.valueOf(60))).isEqualTo("COMPLETED");}@Test void scheduleDistinguishesUnscheduledDays(){var h=habit();h.selectedWeekdays=new Short[]{1,3,5};assertThat(HabitRules.isScheduled(h,LocalDate.of(2026,11,23))).isTrue();assertThat(HabitRules.isScheduled(h,LocalDate.of(2026,11,24))).isFalse();}}
